const icons = require('./dist/icons.json');
// HTML of the Image Builder, generated by build.js from builder/
const builderHtml = require('./dist/builder.js');
// Link preview image of /builder (.github/eyecatch.png), stored as base64 by build.js
const ogImageBase64 = require('./dist/og-image.js');
let ogImage;
const getOgImage = () =>
  (ogImage ??= Uint8Array.from(atob(ogImageBase64), c => c.charCodeAt(0)));
const iconNameList = [...new Set(Object.keys(icons).map(i => i.split('-')[0]))];
// Short name -> canonical name. Names are managed in icons.config.js
const shortNames = Object.fromEntries(
  Object.entries(require('./icons.config')).flatMap(
    ([name, { aliases = [] }]) => aliases.map(alias => [alias, name]),
  ),
);
const themedIcons = [
  ...Object.keys(icons)
    .filter(i => i.includes('-light') || i.includes('-dark'))
    .map(i => i.split('-')[0]),
];

const ICONS_PER_LINE = 15;
const ONE_ICON = 48;
const SCALE = ONE_ICON / (300 - 44);

function generateSvg(iconNames, perLine) {
  const iconSvgList = iconNames.map(i => icons[i]);

  const length = Math.min(perLine * 300, iconNames.length * 300) - 44;
  const height = Math.ceil(iconSvgList.length / perLine) * 300 - 44;
  const scaledHeight = height * SCALE;
  const scaledWidth = length * SCALE;

  return `
  <svg width="${scaledWidth}" height="${scaledHeight}" viewBox="0 0 ${length} ${height}" fill="none" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" version="1.1">
    ${iconSvgList
      .map(
        (i, index) =>
          `
        <g transform="translate(${(index % perLine) * 300}, ${
          Math.floor(index / perLine) * 300
        })">
          ${i}
        </g>
        `,
      )
      .join(' ')}
  </svg>
  `;
}

function parseShortNames(names, theme = 'dark') {
  return names.map(name => {
    if (iconNameList.includes(name))
      return name + (themedIcons.includes(name) ? `-${theme}` : '');
    else if (name in shortNames)
      return (
        shortNames[name] +
        (themedIcons.includes(shortNames[name]) ? `-${theme}` : '')
      );
  });
}

async function handleRequest(request) {
  const { origin, pathname, searchParams } = new URL(request.url);

  const path = pathname.replace(/^\/|\/$/g, '');

  if (path === 'icons') {
    const iconParam = searchParams.get('i') || searchParams.get('icons');
    if (!iconParam)
      return new Response("You didn't specify any icons!", { status: 400 });
    const theme = searchParams.get('t') || searchParams.get('theme');
    if (theme && theme !== 'dark' && theme !== 'light')
      return new Response('Theme must be either "light" or "dark"', {
        status: 400,
      });
    const perLine = searchParams.get('perline') || ICONS_PER_LINE;
    if (isNaN(perLine) || perLine < -1 || perLine > 50)
      return new Response('Icons per line must be a number between 1 and 50', {
        status: 400,
      });

    let iconShortNames = [];
    if (iconParam === 'all') iconShortNames = iconNameList;
    else iconShortNames = iconParam.split(',');

    const iconNames = parseShortNames(iconShortNames, theme || undefined);
    if (!iconNames)
      return new Response("You didn't format the icons param correctly!", {
        status: 400,
      });

    const svg = generateSvg(iconNames, perLine);

    return new Response(svg, { headers: { 'Content-Type': 'image/svg+xml' } });
  } else if (path === 'api/icons') {
    return new Response(JSON.stringify(iconNameList), {
      headers: {
        'content-type': 'application/json;charset=UTF-8',
      },
    });
  } else if (path === 'builder') {
    // The page builds its initial state from the URL in the browser, so the HTML is the same for any query.
    // Only the link preview meta tags need absolute URLs, built from the request origin
    return new Response(builderHtml.replaceAll('__ORIGIN__', origin), {
      headers: { 'content-type': 'text/html; charset=utf-8' },
    });
  } else if (path === 'builder/og.png') {
    return new Response(getOgImage(), {
      headers: {
        'content-type': 'image/png',
        'cache-control': 'public, max-age=86400',
      },
    });
  } else if (path === 'api/svgs') {
    return new Response(JSON.stringify(icons), {
      headers: {
        'content-type': 'application/json;charset=UTF-8',
      },
    });
  } else {
    // Forwarding with fetch(request) loops back to this Worker where there is no origin (wrangler dev,
    // workers.dev) and makes concurrent icon requests fail, so return 404 instead
    return new Response('Not Found', { status: 404 });
  }
}

module.exports = {
  icons,
  iconNameList,
  shortNames,
  themedIcons,
  ICONS_PER_LINE,
  generateSvg,
  parseShortNames,
  handleRequest,
};
